export const presets=[['today','Today'],['yesterday','Yesterday'],['thisMonth','This Month'],['lastMonth','Last Month'],['custom','Custom Range']];
export function singaporeDay(value=new Date()){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);}
function shift(day,n){return new Date(Date.parse(day+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);}
export function dateRange(preset,now=new Date(),start='',end=''){const today=singaporeDay(now),first=today.slice(0,7)+'-01';if(preset==='today')return {start:today,end:today};if(preset==='yesterday'){const day=shift(today,-1);return {start:day,end:day};}if(preset==='lastMonth'){const last=shift(first,-1);return {start:last.slice(0,7)+'-01',end:last};}if(preset==='custom'){if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end)||start>end)throw Error('Choose a valid start and end date.');return {start,end};}const next=new Date(first+'T00:00:00Z');next.setUTCMonth(next.getUTCMonth()+1);return {start:first,end:shift(next.toISOString().slice(0,10),-1)};}
export function inDateRange(value,range){const day=singaporeDay(value);return !!day&&day>=range.start&&day<=range.end;}
